import React, { useState, useRef } from 'react';
import { Student, CourseYear } from '../types';
import { calculateAge, importStudentsFromExcel, exportStudentsToExcel } from '../services/utils';
import { Upload, Download, Plus, Search, ChevronDown, User, Filter } from 'lucide-react';
import { StudentDetail } from './StudentDetail';

interface StudentManagerProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

export const StudentManager: React.FC<StudentManagerProps> = ({ students, setStudents }) => {
  const [selectedCourse, setSelectedCourse] = useState<CourseYear>('1');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Filtros independientes
  const [nameFilter, setNameFilter] = useState('');
  const [dniFilter, setDniFilter] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredStudents = students.filter(
    (s) => {
        const matchesCourse = s.course === selectedCourse;
        const matchesName = String(s.fullName || '').toLowerCase().includes(nameFilter.toLowerCase());
        const matchesDni = String(s.dni || '').includes(dniFilter);
        return matchesCourse && matchesName && matchesDni;
    }
  );

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const newStudents = await importStudentsFromExcel(e.target.files[0], selectedCourse);
        setStudents((prev) => [...prev, ...newStudents]);
        alert(`${newStudents.length} alumnos importados correctamente.`);
      } catch (error) {
        console.error(error);
        alert('Error al importar el archivo. Verifique el formato de las columnas.');
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleExport = () => {
    const toExport = students.filter((s) => s.course === selectedCourse);
    exportStudentsToExcel(toExport, `Alumnos_Curso_${selectedCourse}`);
  };

  const handleAddStudent = () => {
    const newStudent: Student = {
      id: Math.random().toString(36).substr(2, 9),
      fullName: 'Nuevo Alumno',
      birthDate: new Date().toISOString().split('T')[0],
      dni: '',
      address: '',
      course: selectedCourse,
      grades: {},
      attendance: [],
      medical: { treatments: '', medications: '', notes: '' },
      disciplinary: []
    };
    setStudents([...students, newStudent]);
    setSelectedStudent(newStudent);
  };

  const updateStudent = (updated: Student) => {
    setStudents((prev) => prev.map((s) => (s.id === updated.id ? updated : s)));
    setSelectedStudent(updated);
  };

  if (selectedStudent) {
    return (
      <StudentDetail 
        student={selectedStudent} 
        onBack={() => setSelectedStudent(null)} 
        onUpdate={updateStudent}
      />
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-blue-900">Listado de Alumnos</h2>
          <p className="text-gray-500 font-medium">Seleccione el curso y utilice los filtros para buscar alumnos.</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <input type="file" accept=".xlsx" className="hidden" ref={fileInputRef} onChange={handleImport} />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 shadow-sm transition-all"
          >
            <Upload size={18} /> Importar Excel
          </button>
          <button 
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm transition-all"
          >
            <Download size={18} /> Exportar Excel
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex flex-col md:flex-row gap-4 items-end">
          <div className="w-full md:w-64">
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Año/Curso</label>
            <div className="relative">
                <select 
                    value={selectedCourse} 
                    onChange={(e) => setSelectedCourse(e.target.value as CourseYear)}
                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl appearance-none focus:ring-2 focus:ring-blue-500 outline-none font-bold text-blue-900"
                >
                    {['1', '2', '3', '4', '5', '6'].map(year => <option key={year} value={year}>{year}° Año</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-blue-900 pointer-events-none" size={20} />
            </div>
          </div>

          <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Buscar por Apellido y Nombre..." 
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    value={nameFilter}
                    onChange={(e) => setNameFilter(e.target.value)}
                />
            </div>
            <div className="relative">
                <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                <input 
                    type="text" 
                    placeholder="Buscar por DNI..." 
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                    value={dniFilter}
                    onChange={(e) => setDniFilter(e.target.value)}
                />
            </div>
          </div>

          <button 
            onClick={handleAddStudent}
            className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-blue-700 text-white rounded-xl hover:bg-blue-800 font-bold shadow-lg transition-all"
          >
            <Plus size={18} /> AGREGAR ALUMNO
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-md border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-blue-900 text-white text-xs uppercase tracking-widest">
            <tr>
              <th className="p-4 font-black">Apellido y Nombre</th>
              <th className="p-4 font-black">DNI</th>
              <th className="p-4 font-black">Edad Actual</th>
              <th className="p-4 font-black">Domicilio</th>
              <th className="p-4 font-black text-right">Acción</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student) => (
                <tr 
                  key={student.id} 
                  onClick={() => setSelectedStudent(student)}
                  className="hover:bg-blue-50 cursor-pointer transition-colors group"
                >
                  <td className="p-4 flex items-center gap-3">
                    <div className="w-9 h-9 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold">
                      {student.fullName.charAt(0)}
                    </div>
                    <span className="font-bold text-gray-800">{student.fullName}</span>
                  </td>
                  <td className="p-4 text-gray-700 font-medium">{student.dni}</td>
                  <td className="p-4 text-blue-700 font-bold">
                    {calculateAge(student.birthDate)} años
                  </td>
                  <td className="p-4 text-gray-600 truncate max-w-[250px] italic">{student.address}</td>
                  <td className="p-4 text-right">
                     <span className="text-blue-600 text-xs font-black uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-opacity">Ver Ficha &rarr;</span>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="p-16 text-center text-gray-400 font-medium italic">
                  No se encontraron alumnos con los criterios seleccionados.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Student, SUBJECTS_BY_YEAR, AttendanceRecord, Grade } from '../types';
import { calculateAge, getPromotionStatus, exportBulletinToExcel } from '../services/utils';
import { ArrowLeft, Save, AlertTriangle, Printer, FileDown, Plus, HeartPulse, ShieldAlert, GraduationCap } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from 'recharts';

interface StudentDetailProps {
  student: Student;
  onBack: () => void;
  onUpdate: (s: Student) => void;
}

export const StudentDetail: React.FC<StudentDetailProps> = ({ student, onBack, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'info' | 'grades' | 'attendance' | 'medical' | 'discipline'>('info');
  const [isEditing, setIsEditing] = useState(false);
  const [tempStudent, setTempStudent] = useState<Student>({ ...student });

  const subjects = SUBJECTS_BY_YEAR[student.course];
  const promotion = getPromotionStatus(student);

  const handleSave = () => {
    onUpdate(tempStudent);
    setIsEditing(false);
  };

  const getGradeColor = (val?: number) => {
    if (val === undefined) return 'text-gray-300';
    if (val >= 1 && val <= 3) return 'text-red-600 font-black'; // Aplazados Rojo
    if (val >= 4 && val <= 5) return 'text-green-600 font-black'; // Desaprobados Verde
    if (val >= 6 && val <= 10) return 'text-blue-600 font-black'; // Aprobados Azul
    return 'text-gray-800';
  };

  const handleGradeChange = (subject: string, field: keyof Grade, value: string) => {
    const num = parseFloat(value);
    const newGrades = { ...tempStudent.grades };
    if (!newGrades[subject]) newGrades[subject] = {};
    if (isNaN(num)) {
       delete newGrades[subject][field];
    } else {
       newGrades[subject] = { ...newGrades[subject], [field]: Math.min(10, Math.max(1, num)) };
    }
    setTempStudent({ ...tempStudent, grades: newGrades });
  };

  const addAttendance = (type: AttendanceRecord['type'], justified: boolean = false) => {
    const newRecord: AttendanceRecord = {
      date: new Date().toISOString().split('T')[0],
      type,
      justified
    };
    setTempStudent({
      ...tempStudent,
      attendance: [...tempStudent.attendance, newRecord]
    });
  };

  // Estadísticas
  const gradeStats = subjects.reduce((acc, sub) => {
    const final = student.grades[sub]?.final;
    if (final === undefined) return acc;
    if (final <= 3) acc.aplazados++;
    else if (final <= 5) acc.desaprobados++;
    else acc.aprobados++;
    return acc;
  }, { aplazados: 0, desaprobados: 0, aprobados: 0 });

  const chartData = [
    { name: 'Aplazados (1-3)', value: gradeStats.aplazados, color: '#DC2626' },
    { name: 'Desaprobados (4-5)', value: gradeStats.desaprobados, color: '#16A34A' },
    { name: 'Aprobados (6-10)', value: gradeStats.aprobados, color: '#2563EB' },
  ].filter(d => d.value > 0);

  const attendanceTotal = tempStudent.attendance.length;
  const attendanceStats = [
    { name: 'Presente', value: tempStudent.attendance.filter(a => a.type === 'presente').length, color: '#2563EB' },
    { name: 'Ausente', value: tempStudent.attendance.filter(a => a.type === 'ausente').length, color: '#DC2626' },
    { name: 'Tarde', value: tempStudent.attendance.filter(a => a.type === 'tarde').length, color: '#EAB308' },
  ];

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between no-print bg-white p-6 rounded-2xl shadow-md border border-blue-50">
        <div className="flex items-center gap-5">
          <button onClick={onBack} className="p-3 bg-blue-50 hover:bg-blue-100 rounded-full text-blue-600 transition-all">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h2 className="text-3xl font-black text-blue-900 tracking-tight">{student.fullName}</h2>
            <p className="text-sm font-bold text-gray-500 uppercase tracking-widest">
              {student.course}° Año • DNI: {student.dni} • {calculateAge(student.birthDate)} años
            </p>
          </div>
        </div>
        <div className="flex gap-3">
            <button 
                onClick={() => window.print()} 
                className="flex items-center gap-2 px-5 py-2.5 bg-gray-100 text-gray-700 rounded-xl hover:bg-gray-200 transition-all font-bold text-sm shadow-sm"
            >
                <Printer size={18} /> IMPRIMIR INFORME
            </button>
          {isEditing ? (
            <button onClick={handleSave} className="flex items-center gap-2 px-7 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg transition-all font-bold">
              <Save size={18} /> GUARDAR CAMBIOS
            </button>
          ) : (
            <button onClick={() => setIsEditing(true)} className="px-7 py-2.5 bg-white border-2 border-blue-600 text-blue-600 rounded-xl hover:bg-blue-50 transition-all font-bold">
              EDITAR REGISTRO
            </button>
          )}
        </div>
      </div>

      <div className="flex border-b-2 border-gray-100 gap-1 no-print overflow-x-auto">
        {(['info', 'grades', 'attendance', 'medical', 'discipline'] as const).map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-8 py-4 font-black text-xs uppercase tracking-widest transition-all relative ${
              activeTab === tab ? 'text-blue-700 bg-blue-50' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
            }`}
          >
            {tab === 'info' && 'Información'}
            {tab === 'grades' && 'Calificaciones'}
            {tab === 'attendance' && 'Asistencias'}
            {tab === 'medical' && 'Médico'}
            {tab === 'discipline' && 'Disciplina'}
            {activeTab === tab && <div className="absolute bottom-0 left-0 w-full h-1 bg-blue-700" />}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-8 min-h-[650px]">
        {/* Renderizado para impresión */}
        <div className="hidden print-only mb-10 text-center border-b-4 border-blue-900 pb-8">
            <h1 className="text-4xl font-black text-blue-900 uppercase">ESCUELA SECUNDARIA DE LOS BULACIOS</h1>
            <p className="text-base font-bold text-gray-600 mt-2 italic">Ruta 306 Km 22 – Los Bulacio – Dpto. Cruz Alta</p>
            <h2 className="text-2xl mt-8 font-black underline tracking-widest text-black">INFORME INTEGRAL DEL ALUMNO</h2>
            <div className="mt-6 grid grid-cols-2 text-left gap-6 max-w-3xl mx-auto p-6 bg-gray-50 border-2 border-gray-200 rounded-2xl">
              <p className="text-sm font-bold">ALUMNO: <span className="text-blue-900 uppercase">{student.fullName}</span></p>
              <p className="text-sm font-bold">DNI: <span className="text-blue-900">{student.dni}</span></p>
              <p className="text-sm font-bold">AÑO: <span className="text-blue-900">{student.course}° Año</span></p>
              <p className="text-sm font-bold">FECHA REPORTE: <span className="text-blue-900">{new Date().toLocaleDateString('es-AR')}</span></p>
            </div>
        </div>

        {activeTab === 'info' && (
          <div className="grid md:grid-cols-2 gap-16 animate-in fade-in duration-500">
            <div className="space-y-8">
              <h3 className="font-black text-2xl text-blue-900 flex items-center gap-3"><User size={28}/> Datos Personales</h3>
              <div className="grid grid-cols-1 gap-8">
                <div className="flex flex-col border-l-4 border-blue-100 pl-4 py-1">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Nombre Completo</label>
                  {isEditing ? <input className="border-b-2 border-gray-200 focus:border-blue-500 outline-none py-2 text-xl font-bold bg-transparent" value={tempStudent.fullName} onChange={e => setTempStudent({...tempStudent, fullName: e.target.value})} /> : <span className="text-xl font-bold text-gray-900">{student.fullName}</span>}
                </div>
                <div className="flex flex-col border-l-4 border-blue-100 pl-4 py-1">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">DNI</label>
                  {isEditing ? <input className="border-b-2 border-gray-200 focus:border-blue-500 outline-none py-2 text-xl font-bold bg-transparent" value={tempStudent.dni} onChange={e => setTempStudent({...tempStudent, dni: e.target.value})} /> : <span className="text-xl font-bold text-gray-900">{student.dni}</span>}
                </div>
                <div className="flex flex-col border-l-4 border-blue-100 pl-4 py-1">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Fecha de Nacimiento</label>
                  {isEditing ? <input type="date" className="border-b-2 border-gray-200 focus:border-blue-500 outline-none py-2 text-xl font-bold bg-transparent" value={tempStudent.birthDate} onChange={e => setTempStudent({...tempStudent, birthDate: e.target.value})} /> : <span className="text-xl font-bold text-gray-900">{student.birthDate}</span>}
                </div>
                <div className="flex flex-col border-l-4 border-blue-100 pl-4 py-1">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Domicilio Declarado</label>
                  {isEditing ? <input className="border-b-2 border-gray-200 focus:border-blue-500 outline-none py-2 text-xl font-bold bg-transparent" value={tempStudent.address} onChange={e => setTempStudent({...tempStudent, address: e.target.value})} /> : <span className="text-xl font-bold text-gray-900">{student.address}</span>}
                </div>
              </div>
            </div>

            <div className="space-y-8">
                <h3 className="font-black text-2xl text-blue-900 flex items-center gap-3"><GraduationCap size={28}/> Situación Académica</h3>
                <div className={`p-8 rounded-3xl border-2 shadow-sm transition-all flex flex-col items-center text-center ${promotion.status === 'Repite' ? 'bg-red-50 border-red-200 text-red-700' : promotion.status === 'Promocionado' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-green-50 border-green-200 text-green-700'}`}>
                    <AlertTriangle size={48} className="mb-4" />
                    <p className="font-black text-4xl uppercase tracking-tighter mb-2">{promotion.status}</p>
                    <p className="text-sm font-bold opacity-80 mb-4 italic">Espacios curriculares adeudados: {promotion.failedCount}</p>
                    <div className="bg-white/50 p-4 rounded-2xl text-xs font-medium leading-relaxed">
                      {promotion.status === 'Repite' ? '⚠️ Al adeudar 3 o más espacios curriculares, el alumno debe recursar el año lectivo.' : '✅ Cumple con las condiciones de permanencia o promoción.'}
                    </div>
                </div>

                {chartData.length > 0 && (
                  <div className="bg-gray-50 rounded-3xl p-6 border border-gray-100 shadow-inner">
                    <p className="text-[10px] font-black text-center text-gray-400 uppercase tracking-[0.2em] mb-6">Rendimiento por Escala</p>
                    <div className="h-64 w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                            {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />)}
                          </Pie>
                          <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 15px 30px -10px rgba(0,0,0,0.1)' }} />
                          <Legend verticalAlign="bottom" iconType="circle" />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                )}
            </div>
          </div>
        )}

        {activeTab === 'grades' && (
          <div className="animate-in slide-in-from-right-4 duration-500">
            <div className="flex justify-between items-center mb-8 no-print">
               <h3 className="font-black text-2xl text-blue-900">Panel de Calificaciones</h3>
               <button 
                 onClick={() => exportBulletinToExcel(student, "ESCUELA SECUNDARIA DE LOS BULACIOS")}
                 className="flex items-center gap-3 px-6 py-3 bg-green-50 text-green-700 rounded-2xl hover:bg-green-100 font-black text-xs uppercase tracking-widest transition-all shadow-sm border border-green-100"
               >
                 <FileDown size={18} /> DESCARGAR BOLETÍN (.XLSX)
               </button>
            </div>
            <div className="overflow-x-auto rounded-3xl border-2 border-gray-50 shadow-sm">
              <table className="w-full border-collapse text-sm">
                <thead>
                  <tr className="bg-blue-900 text-white uppercase text-[10px] font-black tracking-[0.15em]">
                    <th className="p-5 text-left w-1/3">Espacio Curricular</th>
                    <th className="p-5 text-center">1° Trimestre</th>
                    <th className="p-5 text-center">2° Trimestre</th>
                    <th className="p-5 text-center">3° Trimestre</th>
                    <th className="p-5 text-center bg-blue-800">Nota Final</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {subjects.map(subject => {
                    const grade = tempStudent.grades[subject] || {};
                    return (
                      <tr key={subject} className="hover:bg-blue-50/30 transition-colors">
                        <td className="p-5 font-bold text-gray-700">{subject}</td>
                        {['trimestre1', 'trimestre2', 'trimestre3', 'final'].map((field) => (
                          <td key={field} className={`p-3 text-center ${field === 'final' ? 'bg-blue-50/20' : ''}`}>
                            {isEditing ? (
                              <input 
                                type="number" 
                                className={`w-16 text-center border-b-2 border-transparent focus:border-blue-500 bg-transparent py-2 font-black text-lg ${getGradeColor(grade[field as keyof Grade])}`}
                                value={grade[field as keyof Grade] ?? ''}
                                onChange={(e) => handleGradeChange(subject, field as keyof Grade, e.target.value)}
                                min="1" max="10"
                              />
                            ) : (
                              <span className={`text-xl ${getGradeColor(grade[field as keyof Grade])}`}>
                                {grade[field as keyof Grade] || '-'}
                              </span>
                            )}
                          </td>
                        ))}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <div className="mt-10 grid grid-cols-3 gap-8 no-print">
               <div className="p-6 rounded-3xl border-2 border-red-50 bg-red-50/20 text-center shadow-sm">
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-2">Aplazados (1-3)</p>
                  <p className="text-4xl font-black text-red-700">{gradeStats.aplazados}</p>
               </div>
               <div className="p-6 rounded-3xl border-2 border-green-50 bg-green-50/20 text-center shadow-sm">
                  <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-2">Desaprobados (4-5)</p>
                  <p className="text-4xl font-black text-green-700">{gradeStats.desaprobados}</p>
               </div>
               <div className="p-6 rounded-3xl border-2 border-blue-50 bg-blue-50/20 text-center shadow-sm">
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-2">Aprobados (6-10)</p>
                  <p className="text-4xl font-black text-blue-700">{gradeStats.aprobados}</p>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'attendance' && (
          <div className="animate-in slide-in-from-right-4 duration-500">
            <div className="flex justify-between items-center mb-10 no-print">
               <h3 className="font-black text-2xl text-blue-900">Registro de Asistencia</h3>
               <div className="flex gap-4">
                 <button onClick={() => addAttendance('presente')} className="bg-blue-600 text-white px-7 py-3 rounded-2xl hover:bg-blue-700 text-xs font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Presente</button>
                 <button onClick={() => addAttendance('tarde')} className="bg-yellow-500 text-white px-7 py-3 rounded-2xl hover:bg-yellow-600 text-xs font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Tarde</button>
                 <button onClick={() => addAttendance('ausente')} className="bg-red-500 text-white px-7 py-3 rounded-2xl hover:bg-red-600 text-xs font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Ausente</button>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-8 mb-10">
               <div className="bg-gray-900 p-8 rounded-3xl text-center shadow-xl">
                  <span className="block text-5xl font-black text-white">{attendanceTotal}</span>
                  <span className="text-[10px] font-bold text-blue-300 uppercase tracking-widest mt-2 block">Días Registrados</span>
               </div>
               {attendanceStats.map(stat => (
                 <div key={stat.name} className="p-8 rounded-3xl border-2 border-gray-50 text-center shadow-sm" style={{ backgroundColor: `${stat.color}08` }}>
                    <span className="block text-5xl font-black" style={{ color: stat.color }}>{stat.value}</span>
                    <span className="text-[10px] font-black uppercase tracking-widest mt-2 block" style={{ color: stat.color }}>{stat.name}s</span>
                 </div>
               ))}
            </div>

            <div className="bg-white rounded-3xl border-2 border-gray-50 overflow-hidden shadow-sm">
               <div className="p-5 bg-gray-50 border-b font-black text-xs uppercase tracking-[0.2em] text-gray-500">Historial de Ciclo Lectivo</div>
               <div className="max-h-96 overflow-y-auto">
                 <table className="w-full text-sm">
                   <tbody className="divide-y divide-gray-50">
                      {[...tempStudent.attendance].reverse().map((att, idx) => (
                        <tr key={idx} className="hover:bg-gray-50 transition-colors">
                          <td className="p-5 text-gray-800 font-bold uppercase text-xs">{new Date(att.date).toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })}</td>
                          <td className="p-5">
                             <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest
                               ${att.type === 'presente' ? 'bg-blue-100 text-blue-700' : att.type === 'ausente' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}
                             `}>
                               {att.type}
                             </span>
                          </td>
                          <td className="p-5 text-gray-400 italic text-xs text-right font-medium">
                             {att.justified ? 'Justificada con Certificado' : 'Sin Observaciones'}
                          </td>
                        </tr>
                      ))}
                      {tempStudent.attendance.length === 0 && (
                        <tr><td colSpan={3} className="p-20 text-center text-gray-400 italic font-bold">Sin registros cargados actualmente.</td></tr>
                      )}
                   </tbody>
                 </table>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'medical' && (
           <div className="animate-in slide-in-from-right-4 duration-500 space-y-10">
             <div className="flex items-center gap-4 border-l-8 border-blue-600 pl-6 py-2">
                <HeartPulse size={36} className="text-blue-600"/>
                <h3 className="text-3xl font-black text-blue-900 uppercase tracking-tight">Ficha Médica y Sanitaria</h3>
             </div>
             <div className="grid gap-10">
               <div className="bg-blue-50/30 p-8 rounded-3xl border-2 border-blue-100 shadow-sm relative">
                  <label className="absolute -top-4 left-8 px-4 py-1 bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest rounded-full">Tratamientos Vigentes</label>
                  {isEditing ? (
                    <textarea className="w-full bg-white border-2 border-blue-100 rounded-2xl p-6 focus:ring-4 focus:ring-blue-100 outline-none text-gray-700 font-medium" rows={5} value={tempStudent.medical.treatments} onChange={e => setTempStudent({...tempStudent, medical: {...tempStudent.medical, treatments: e.target.value}})} placeholder="Describa diagnósticos y tratamientos actuales..." />
                  ) : <div className="min-h-[120px] text-gray-700 leading-relaxed font-bold text-lg">{student.medical.treatments || 'No se declaran tratamientos específicos.'}</div>}
               </div>
               <div className="bg-red-50/30 p-8 rounded-3xl border-2 border-red-100 shadow-sm relative">
                  <label className="absolute -top-4 left-8 px-4 py-1 bg-red-600 text-white text-[10px] font-black uppercase tracking-widest rounded-full">Medicación Requerida</label>
                  {isEditing ? (
                    <textarea className="w-full bg-white border-2 border-red-100 rounded-2xl p-6 focus:ring-4 focus:ring-red-100 outline-none text-gray-700 font-medium" rows={5} value={tempStudent.medical.medications} onChange={e => setTempStudent({...tempStudent, medical: {...tempStudent.medical, medications: e.target.value}})} placeholder="Indique fármacos, dosis y horarios si corresponde..." />
                  ) : <div className="min-h-[120px] text-gray-700 leading-relaxed font-bold text-lg">{student.medical.medications || 'No requiere administración de medicación en horario escolar.'}</div>}
               </div>
             </div>
           </div>
        )}

        {activeTab === 'discipline' && (
           <div className="animate-in slide-in-from-right-4 duration-500 space-y-10">
              <div className="flex justify-between items-center border-l-8 border-red-600 pl-6 py-2">
                 <div className="flex items-center gap-4">
                    <ShieldAlert size={36} className="text-red-600"/>
                    <h3 className="text-3xl font-black text-blue-900 uppercase tracking-tight">Llamados de Atención</h3>
                 </div>
                 {isEditing && (
                   <button 
                     onClick={() => {
                        const reason = prompt('Ingrese el motivo del llamado de atención:');
                        if (reason) setTempStudent({...tempStudent, disciplinary: [...tempStudent.disciplinary, `${new Date().toLocaleDateString('es-AR')}: ${reason}`]});
                     }}
                     className="flex items-center gap-3 px-6 py-3 bg-red-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-red-700 transition-all shadow-xl active:scale-95"
                   >
                     <Plus size={18} /> REGISTRAR NOVEDAD
                   </button>
                 )}
              </div>
              <div className="space-y-6">
                {tempStudent.disciplinary.length > 0 ? [...tempStudent.disciplinary].reverse().map((note, idx) => (
                  <div key={idx} className="p-8 bg-white border-l-8 border-red-600 rounded-2xl shadow-md flex gap-6 items-start transition-all hover:translate-x-2">
                    <div className="bg-red-100 p-3 rounded-full text-red-600">
                      <AlertTriangle size={24} />
                    </div>
                    <div className="flex-1">
                      <p className="text-gray-900 font-bold text-lg leading-relaxed">{note}</p>
                    </div>
                  </div>
                )) : (
                  <div className="p-20 text-center bg-gray-50 rounded-3xl border-4 border-dashed border-gray-100 text-gray-400 italic font-black text-xl">
                    CONDUCTA EJEMPLAR. SIN REGISTROS DE DISCIPLINA.
                  </div>
                )}
              </div>
           </div>
        )}
      </div>

      <div className="hidden print-only mt-24 grid grid-cols-3 gap-16 text-center text-[10px] font-black uppercase">
         <div className="flex flex-col items-center">
            <div className="w-48 border-t-2 border-black mb-2"></div>
            <span>Firma del Directivo</span>
         </div>
         <div className="flex flex-col items-center">
            <div className="w-48 border-t-2 border-black mb-2"></div>
            <span>Firma de los Padres / Tutor</span>
         </div>
         <div className="flex flex-col items-center">
            <div className="w-48 border-t-2 border-black mb-2"></div>
            <span>Firma del Preceptor/a</span>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Teacher, CourseYear, SUBJECTS_BY_YEAR, TeacherAttendance, LicenseRecord } from '../types';
import { importTeachersFromExcel, exportTeacherReportToExcel, exportExTeachersToExcel } from '../services/utils';
import { Upload, Plus, Search, UserCheck, Trash2, FileText, Briefcase, GraduationCap, X, Edit3, Save } from 'lucide-react';

interface TeacherManagerProps {
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exTeachers: Teacher[];
  setExTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
}

export const TeacherManager: React.FC<TeacherManagerProps> = ({ teachers, setTeachers, exTeachers, setExTeachers }) => {
  const [selectedTeacher, setSelectedTeacher] = useState<Teacher | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [tempTeacher, setTempTeacher] = useState<Teacher | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Novedades/Licencias Modal
  const [showLicenseModal, setShowLicenseModal] = useState(false);
  const [licenseCode, setLicenseCode] = useState('');
  const [attendanceType, setAttendanceType] = useState<TeacherAttendance['type']>('licencia');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [presentationDate, setPresentationDate] = useState('');

  // Asignación de Materias
  const [assignCourse, setAssignCourse] = useState<CourseYear>('1');
  const [assignSubject, setAssignSubject] = useState('');

  const filteredTeachers = teachers.filter(t => 
    String(t.fullName || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
    String(t.dni || '').includes(searchTerm)
  );

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const newTeachers = await importTeachersFromExcel(e.target.files[0]);
        setTeachers(prev => [...prev, ...newTeachers]);
        alert(`${newTeachers.length} docentes importados correctamente.`);
      } catch (err) {
        alert('Error al importar docentes. Verifique que las columnas coincidan con el formato solicitado.');
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleEditToggle = () => {
    if (isEditing && tempTeacher) {
        setTeachers(prev => prev.map(t => t.id === tempTeacher.id ? tempTeacher : t));
        setSelectedTeacher(tempTeacher);
        setIsEditing(false);
    } else {
        setTempTeacher({ ...selectedTeacher! });
        setIsEditing(true);
    }
  };

  const saveAttendance = () => {
    if (!selectedTeacher) return;

    const licenseDetails: LicenseRecord | undefined = attendanceType === 'licencia' ? {
      type: licenseCode,
      from: dateFrom,
      to: dateTo,
      presentationDate: presentationDate,
      licenseCode: licenseCode
    } : undefined;

    const newRecord: TeacherAttendance = {
      date: new Date().toISOString().split('T')[0],
      type: attendanceType,
      licenseCode: attendanceType === 'licencia' ? licenseCode : undefined,
      licenseDetails
    };

    const updated = { ...selectedTeacher, attendance: [...selectedTeacher.attendance, newRecord] };
    setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t));
    setSelectedTeacher(updated);

    // Reset campos
    setLicenseCode('');
    setDateFrom('');
    setDateTo('');
    setPresentationDate('');
    setShowLicenseModal(false);
  };

  const assignWork = () => {
    if (!selectedTeacher || !assignSubject) return;
    const exists = selectedTeacher.assignedCourses.some(c => c.course === assignCourse && c.subject === assignSubject);
    if (exists) {
      alert('Esta materia ya está asignada a este docente.');
      return;
    }
    const updated = { 
      ...selectedTeacher, 
      assignedCourses: [...selectedTeacher.assignedCourses, { course: assignCourse, subject: assignSubject }] 
    };
    setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t));
    setSelectedTeacher(updated);
  };

  const deleteTeacher = (id: string) => {
    const teacher = teachers.find(t => t.id === id);
    if (!teacher) return;
    if (confirm(`¿ELIMINAR DOCENTE? El registro de ${teacher.fullName} se trasladará a la base de datos de EX-DOCENTES.`)) {
      const removedTeacher = { ...teacher, exitDate: new Date().toISOString().split('T')[0] };
      setExTeachers(prev => [...prev, removedTeacher]);
      setTeachers(prev => prev.filter(t => t.id !== id));
      setSelectedTeacher(null);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-blue-900 tracking-tight">Planta Personal Docente</h2>
          <p className="text-gray-500 font-bold uppercase text-[10px] tracking-[0.2em]">Escuela Secundaria Los Bulacios</p>
        </div>
        <div className="flex flex-wrap gap-3">
            <input type="file" className="hidden" ref={fileInputRef} accept=".xlsx" onChange={handleImport} />
            <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-2xl hover:bg-green-700 shadow-lg transition-all active:scale-95 text-xs font-black uppercase tracking-widest">
                <Upload size={18} /> Importar Planta (.xlsx)
            </button>
            <button onClick={() => exportExTeachersToExcel(exTeachers)} className="flex items-center gap-2 px-6 py-3 bg-gray-900 text-white rounded-2xl hover:bg-black shadow-lg transition-all active:scale-95 text-xs font-black uppercase tracking-widest">
                <Download size={18} /> BBDD Ex-Docentes
            </button>
        </div>
      </div>

      <div className="grid lg:grid-cols-12 gap-8">
         <div className="lg:col-span-4 bg-white rounded-3xl shadow-md border border-gray-50 flex flex-col h-[750px] overflow-hidden">
            <div className="p-6 border-b-2 border-gray-50 bg-gray-50/50">
                <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-900" size={20} />
                    <input 
                      className="w-full border-2 border-transparent bg-white rounded-2xl pl-12 pr-4 py-4 text-sm font-bold shadow-sm focus:border-blue-500 transition-all outline-none" 
                      placeholder="Buscar por Nombre o DNI..."
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
                {filteredTeachers.map(teacher => (
                    <div 
                      key={teacher.id}
                      onClick={() => { setSelectedTeacher(teacher); setIsEditing(false); }}
                      className={`group p-5 rounded-2xl cursor-pointer transition-all flex items-center justify-between border-2 ${selectedTeacher?.id === teacher.id ? 'bg-blue-600 border-blue-600 text-white shadow-xl translate-x-1' : 'bg-white border-transparent hover:border-blue-100 text-gray-700 hover:bg-blue-50'}`}
                    >
                        <div>
                          <p className={`font-black text-lg leading-tight ${selectedTeacher?.id === teacher.id ? 'text-white' : 'text-blue-900'}`}>{teacher.fullName}</p>
                          <p className={`text-[10px] font-black uppercase tracking-widest mt-1 ${selectedTeacher?.id === teacher.id ? 'text-blue-200' : 'text-gray-400'}`}>Legajo: {teacher.legajo} • {teacher.hours} Horas</p>
                        </div>
                        <button 
                          onClick={(e) => { e.stopPropagation(); deleteTeacher(teacher.id); }}
                          className="w-10 h-10 rounded-full bg-red-600 text-white flex items-center justify-center shadow-lg hover:bg-red-700 transition-all active:scale-90"
                          title="Eliminar Docente"
                        >
                          <Trash2 size={18} />
                        </button>
                    </div>
                ))}
            </div>
         </div>

         <div className="lg:col-span-8">
            {selectedTeacher ? (
                <div className="bg-white rounded-3xl shadow-xl border border-gray-50 p-10 space-y-10 animate-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col md:flex-row justify-between items-start gap-6 border-b-2 border-gray-50 pb-8">
                     <div>
                       <div className="flex items-center gap-3 mb-2">
                          <h3 className="text-4xl font-black text-blue-900 tracking-tighter leading-none">{isEditing ? tempTeacher?.fullName : selectedTeacher.fullName}</h3>
                          <span className="px-3 py-1 bg-green-100 text-green-700 text-[10px] font-black rounded-full uppercase tracking-widest">Activo</span>
                       </div>
                       <p className="text-gray-400 font-bold uppercase text-xs tracking-widest">Legajo Institucional: {selectedTeacher.legajo}</p>
                     </div>
                     <div className="flex gap-2">
                        <button 
                            onClick={handleEditToggle}
                            className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg transition-all active:scale-95 ${isEditing ? 'bg-green-600 text-white hover:bg-green-700' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
                        >
                            {isEditing ? <><Save size={18}/> Guardar Registro</> : <><Edit3 size={18}/> Editar Registro</>}
                        </button>
                        <button 
                           onClick={() => exportTeacherReportToExcel(selectedTeacher)}
                           className="flex items-center gap-2 px-6 py-3 bg-[#6B46C1] text-white rounded-2xl hover:bg-[#553C9A] shadow-lg transition-all font-black text-xs uppercase tracking-widest"
                        >
                           <FileText size={18} /> Generar Informe
                        </button>
                     </div>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">DNI / Documento</p>
                        {isEditing ? <input className="w-full bg-white border-b-2 border-blue-500 p-1 font-bold" value={tempTeacher?.dni} onChange={e => setTempTeacher({...tempTeacher!, dni: e.target.value})} /> : <p className="font-black text-blue-900 text-xl">{selectedTeacher.dni}</p>}
                      </div>
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Contacto Directo</p>
                        {isEditing ? <input className="w-full bg-white border-b-2 border-blue-500 p-1 font-bold" value={tempTeacher?.phone} onChange={e => setTempTeacher({...tempTeacher!, phone: e.target.value})} /> : <p className="font-bold text-gray-800">{selectedTeacher.phone || 'No registrado'}</p>}
                        <p className="text-[10px] text-blue-500 font-bold truncate">{selectedTeacher.email}</p>
                      </div>
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Fecha Ingreso</p>
                        <p className="font-black text-blue-900 text-xl">{selectedTeacher.entryDate}</p>
                      </div>
                   </div>

                   <div className="bg-blue-900/5 p-8 rounded-3xl border-2 border-blue-900/10">
                      <h4 className="font-black text-blue-900 mb-6 flex items-center gap-3 uppercase text-lg tracking-tight"><GraduationCap size={24}/> Asignación de Espacios Curriculares</h4>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end mb-6">
                        <div>
                          <label className="text-[10px] font-black text-gray-400 uppercase block mb-2 ml-2">Seleccionar Año</label>
                          <select className="w-full border-2 border-gray-100 rounded-2xl p-4 text-sm font-bold bg-white outline-none focus:border-blue-500 transition-all" value={assignCourse} onChange={e => setAssignCourse(e.target.value as any)}>
                            {['1','2','3','4','5','6'].map(y => <option key={y} value={y}>{y}° Año</option>)}
                          </select>
                        </div>
                        <div>
                          <label className="text-[10px] font-black text-gray-400 uppercase block mb-2 ml-2">Espacio Curricular</label>
                          <select className="w-full border-2 border-gray-100 rounded-2xl p-4 text-sm font-bold bg-white outline-none focus:border-blue-500 transition-all" value={assignSubject} onChange={e => setAssignSubject(e.target.value)}>
                            <option value="">Seleccionar Materia...</option>
                            {SUBJECTS_BY_YEAR[assignCourse].map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                        </div>
                        <button onClick={assignWork} className="bg-blue-900 text-white p-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl active:scale-95">Asignar Espacio</button>
                      </div>
                      <div className="flex flex-wrap gap-3">
                        {selectedTeacher.assignedCourses.map((c, i) => (
                          <div key={i} className="flex items-center gap-3 bg-white border-2 border-blue-100 px-5 py-3 rounded-2xl text-blue-900 text-sm font-black shadow-sm group">
                            <span>{c.course}° AÑO - {c.subject}</span>
                            <button onClick={() => { if(confirm('¿Desasignar materia?')) { const updated = {...selectedTeacher, assignedCourses: selectedTeacher.assignedCourses.filter((_, idx) => idx !== i)}; setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t)); setSelectedTeacher(updated); } }} className="text-gray-300 hover:text-red-600 transition-colors"><X size={18}/></button>
                          </div>
                        ))}
                        {selectedTeacher.assignedCourses.length === 0 && <p className="text-sm text-gray-400 italic font-medium p-4 border-2 border-dashed border-gray-200 rounded-2xl w-full text-center uppercase tracking-widest">Sin espacios curriculares asignados</p>}
                      </div>
                   </div>

                   <div className="space-y-6">
                      <div className="flex justify-between items-center">
                        <h4 className="font-black text-blue-900 flex items-center gap-3 uppercase text-lg tracking-tight"><Briefcase size={24}/> Registro de Novedades y Licencias</h4>
                        <button 
                          onClick={() => setShowLicenseModal(true)}
                          className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-blue-700 shadow-xl transition-all active:scale-95"
                        >
                          + Registrar Novedad
                        </button>
                      </div>

                      <div className="max-h-72 overflow-y-auto rounded-3xl border-2 border-gray-50 bg-white shadow-inner">
                        <table className="w-full text-left text-sm">
                           <thead className="bg-gray-900 text-white sticky top-0 font-black text-[10px] uppercase tracking-[0.2em]">
                               <tr><th className="p-5">Fecha</th><th className="p-5">Motivo Novedad</th><th className="p-5">Cód. Licencia</th><th className="p-5">Periodo</th></tr>
                           </thead>
                           <tbody className="divide-y divide-gray-50 text-black">
                               {[...selectedTeacher.attendance].reverse().map((att, i) => (
                                   <tr key={i} className="hover:bg-gray-50 transition-colors">
                                       <td className="p-5 font-bold text-blue-900">{att.date}</td>
                                       <td className="p-5">
                                         <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${att.type === 'licencia' ? 'bg-purple-100 text-purple-700' : 'bg-gray-100 text-gray-700'}`}>
                                           {att.type.replace('_', ' ')}
                                         </span>
                                       </td>
                                       <td className="p-5 font-black text-lg">{att.licenseCode || '-'}</td>
                                       <td className="p-5 text-gray-500 font-bold text-xs italic">
                                         {att.licenseDetails ? `${att.licenseDetails.from} al ${att.licenseDetails.to}` : 'Novedad Puntual'}
                                       </td>
                                   </tr>
                               ))}
                               {selectedTeacher.attendance.length === 0 && (
                                 <tr><td colSpan={4} className="p-20 text-center text-gray-300 font-black uppercase tracking-widest italic">Sin novedades asentadas</td></tr>
                               )}
                           </tbody>
                        </table>
                      </div>
                   </div>
                </div>
            ) : (
                <div className="bg-white rounded-[40px] border-4 border-dashed border-gray-100 h-full flex flex-col items-center justify-center text-gray-200 min-h-[550px] space-y-6">
                    <div className="bg-gray-50 p-10 rounded-full">
                      <UserCheck size={100} className="opacity-10 text-blue-900"/>
