        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Layout } from './components/Layout';
import { StudentManager } from './components/StudentManager';
import { TeacherManager } from './components/TeacherManager';
import { Student, Teacher } from './types';
import { calculateAge } from './services/utils';
// Added missing GraduationCap import
import { Gift, CalendarDays, PartyPopper, GraduationCap } from 'lucide-react';

const INITIAL_STUDENTS: Student[] = [];
const INITIAL_TEACHERS: Teacher[] = [];
const INITIAL_EX_TEACHERS: Teacher[] = [];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('students');
  const [students, setStudents] = useState<Student[]>(() => {
    const saved = localStorage.getItem('bulacios_students');
    return saved ? JSON.parse(saved) : INITIAL_STUDENTS;
  });
  const [teachers, setTeachers] = useState<Teacher[]>(() => {
    const saved = localStorage.getItem('bulacios_teachers');
    return saved ? JSON.parse(saved) : INITIAL_TEACHERS;
  });
  const [exTeachers, setExTeachers] = useState<Teacher[]>(() => {
    const saved = localStorage.getItem('bulacios_ex_teachers');
    return saved ? JSON.parse(saved) : INITIAL_EX_TEACHERS;
  });

  // Persistence
  useEffect(() => {
    localStorage.setItem('bulacios_students', JSON.stringify(students));
  }, [students]);

  useEffect(() => {
    localStorage.setItem('bulacios_teachers', JSON.stringify(teachers));
  }, [teachers]);

  useEffect(() => {
    localStorage.setItem('bulacios_ex_teachers', JSON.stringify(exTeachers));
  }, [exTeachers]);

  // Lógica de cumpleaños
  const todaysBirthdays = useMemo(() => {
    const today = new Date();
    const currentDay = today.getDate();
    const currentMonth = today.getMonth() + 1;

    return students.filter(student => {
      const parts = student.birthDate.split('-');
      if (parts.length !== 3) return false;
      const birthMonth = parseInt(parts[1], 10);
      const birthDay = parseInt(parts[2], 10);
      return birthMonth === currentMonth && birthDay === currentDay;
    });
  }, [students]);

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === 'students' && (
        <StudentManager students={students} setStudents={setStudents} />
      )}
      {activeTab === 'teachers' && (
        <TeacherManager 
          teachers={teachers} 
          setTeachers={setTeachers} 
          exTeachers={exTeachers} 
          setExTeachers={setExTeachers} 
        />
      )}
      {activeTab === 'reports' && (
        <div className="space-y-10 animate-in fade-in duration-500 pb-12">
           <div className="text-center space-y-2">
             <h2 className="text-4xl font-black text-gray-800 tracking-tight">Panel de Control Institucional</h2>
             <p className="text-lg text-gray-500 font-medium">Resumen y novedades del Ciclo Lectivo {new Date().getFullYear()}</p>
           </div>

           {/* Notificación de Cumpleaños */}
           {todaysBirthdays.length > 0 ? (
             <div className="bg-gradient-to-r from-amber-50 to-yellow-50 border-2 border-amber-200 rounded-[32px] p-8 shadow-sm flex flex-col md:flex-row items-center gap-8 animate-in slide-in-from-top-4 duration-700">
                <div className="bg-amber-500 text-white p-5 rounded-3xl shadow-lg transform -rotate-6">
                   <Gift size={40} />
                </div>
                <div className="flex-1 text-center md:text-left">
                   <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                      <PartyPopper size={20} className="text-amber-600" />
                      <h3 className="text-xl font-black text-amber-900 uppercase tracking-tight">¡Hoy celebramos cumpleaños!</h3>
                   </div>
                   <p className="text-amber-700 font-medium">Los siguientes alumnos cumplen años hoy {new Date().toLocaleDateString('es-AR', { day: 'numeric', month: 'long' })}:</p>
                   <div className="mt-4 flex flex-wrap gap-3 justify-center md:justify-start">
                      {todaysBirthdays.map(student => (
                        <div key={student.id} className="bg-white px-5 py-2.5 rounded-2xl border border-amber-200 shadow-sm flex items-center gap-3 transition-transform hover:scale-105">
                           <span className="w-8 h-8 rounded-full bg-amber-100 text-amber-700 flex items-center justify-center font-black text-xs">{student.fullName.charAt(0)}</span>
                           <span className="font-bold text-gray-800">{student.fullName} <span className="text-amber-600 ml-1">({calculateAge(student.birthDate)} años)</span></span>
                        </div>
                      ))}
                   </div>
                </div>
             </div>
           ) : (
             <div className="bg-white border-2 border-dashed border-gray-100 rounded-[32px] p-10 flex flex-col items-center justify-center text-gray-300">
                <CalendarDays size={48} className="mb-4 opacity-20" />
                <p className="font-bold uppercase tracking-widest text-xs">No hay cumpleaños registrados para el día de hoy</p>
             </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-6xl mx-auto">
              <div className="bg-white p-8 rounded-3xl shadow-xl text-center border-b-8 border-blue-500 transform hover:-translate-y-2 transition-transform">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Población Estudiantil</p>
                  <h3 className="font-black text-5xl text-blue-600">{students.length}</h3>
                  <p className="text-gray-500 mt-2 font-medium">Alumnos Activos</p>
              </div>
              <div className="bg-white p-8 rounded-3xl shadow-xl text-center border-b-8 border-green-500 transform hover:-translate-y-2 transition-transform">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Planta Funcional</p>
                  <h3 className="font-black text-5xl text-green-600">{teachers.length}</h3>
                  <p className="text-gray-500 mt-2 font-medium">Docentes en Ejercicio</p>
              </div>
              <div className="bg-white p-8 rounded-3xl shadow-xl text-center border-b-8 border-purple-500 transform hover:-translate-y-2 transition-transform">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Desvinculaciones</p>
                  <h3 className="font-black text-5xl text-purple-600">{exTeachers.length}</h3>
                  <p className="text-gray-500 mt-2 font-medium">Historial Ex-Docentes</p>
              </div>
           </div>

           <div className="bg-blue-900 text-white p-8 rounded-[40px] max-w-4xl mx-auto shadow-2xl relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 opacity-10">
                 <GraduationCap size={120} />
              </div>
              <div className="relative z-10 space-y-4">
                 <h4 className="text-2xl font-black uppercase tracking-tighter italic">Compromiso Educativo</h4>
                 <p className="text-blue-100 leading-relaxed font-medium">
                   "La Escuela Secundaria de Los Bulacios se compromete día a día con la formación integral de nuestros jóvenes en la comuna de Los Bulacio, Dpto. Cruz Alta. Este sistema centralizado permite optimizar la toma de decisiones pedagógicas y administrativas para asegurar una educación de calidad."
                 </p>
                 <div className="pt-4 flex flex-wrap gap-4">
                    <div className="bg-blue-800/50 px-4 py-2 rounded-xl text-xs font-bold border border-blue-700">Gestión de Boletines Digitales</div>
                    <div className="bg-blue-800/50 px-4 py-2 rounded-xl text-xs font-bold border border-blue-700">Control Biométrico de Asistencia</div>
                    <div className="bg-blue-800/50 px-4 py-2 rounded-xl text-xs font-bold border border-blue-700">Legajo Único de Alumno</div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Teacher, CourseYear, SUBJECTS_BY_YEAR, TeacherAttendance, LicenseRecord } from '../types';
import { importTeachersFromExcel, exportTeacherReportToExcel, exportExTeachersToExcel } from '../services/utils';
// Fixed missing 'Download' import from lucide-react
import { Upload, Download, Plus, Search, UserCheck, Trash2, FileText, Briefcase, GraduationCap, X, Edit3, Save, Filter, ChevronDown } from 'lucide-react';

interface TeacherManagerProps {
  teachers: Teacher[];
  setTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
  exTeachers: Teacher[];
  setExTeachers: React.Dispatch<React.SetStateAction<Teacher[]>>;
}

export const TeacherManager: React.FC<TeacherManagerProps> = ({ teachers, setTeachers, exTeachers, setExTeachers }) => {
  const [selectedTeacher, setSelectedTeacher] = useState<Teacher | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState<CourseYear | 'all'>('all');
  const [isEditing, setIsEditing] = useState(false);
  const [tempTeacher, setTempTeacher] = useState<Teacher | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Novedades/Licencias Modal
  const [showLicenseModal, setShowLicenseModal] = useState(false);
  const [licenseCode, setLicenseCode] = useState('');
  const [attendanceType, setAttendanceType] = useState<TeacherAttendance['type']>('licencia');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [presentationDate, setPresentationDate] = useState('');

  // Asignación de Materias
  const [assignCourse, setAssignCourse] = useState<CourseYear>('1');
  const [assignSubject, setAssignSubject] = useState('');

  const filteredTeachers = teachers.filter(t => {
    const matchesSearch = String(t.fullName || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                         String(t.dni || '').includes(searchTerm);
    const matchesCourse = courseFilter === 'all' || t.assignedCourses.some(c => c.course === courseFilter);
    return matchesSearch && matchesCourse;
  });

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const newTeachers = await importTeachersFromExcel(e.target.files[0]);
        setTeachers(prev => [...prev, ...newTeachers]);
        alert(`${newTeachers.length} docentes importados correctamente.`);
      } catch (err) {
        alert('Error al importar docentes. Verifique que las columnas coincidan con el formato solicitado.');
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleEditToggle = () => {
    if (isEditing && tempTeacher) {
        setTeachers(prev => prev.map(t => t.id === tempTeacher.id ? tempTeacher : t));
        setSelectedTeacher(tempTeacher);
        setIsEditing(false);
    } else {
        setTempTeacher({ ...selectedTeacher! });
        setIsEditing(true);
    }
  };

  const saveAttendance = () => {
    if (!selectedTeacher) return;

    const licenseDetails: LicenseRecord | undefined = attendanceType === 'licencia' ? {
      type: licenseCode,
      from: dateFrom,
      to: dateTo,
      presentationDate: presentationDate,
      licenseCode: licenseCode
    } : undefined;

    const newRecord: TeacherAttendance = {
      date: new Date().toISOString().split('T')[0],
      type: attendanceType,
      licenseCode: attendanceType === 'licencia' ? licenseCode : undefined,
      licenseDetails
    };

    const updated = { ...selectedTeacher, attendance: [...selectedTeacher.attendance, newRecord] };
    setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t));
    setSelectedTeacher(updated);

    // Reset campos
    setLicenseCode('');
    setDateFrom('');
    setDateTo('');
    setPresentationDate('');
    setShowLicenseModal(false);
  };

  const assignWork = () => {
    if (!selectedTeacher || !assignSubject) return;
    const exists = selectedTeacher.assignedCourses.some(c => c.course === assignCourse && c.subject === assignSubject);
    if (exists) {
      alert('Esta materia ya está asignada a este docente.');
      return;
    }
    const updated = { 
      ...selectedTeacher, 
      assignedCourses: [...selectedTeacher.assignedCourses, { course: assignCourse, subject: assignSubject }] 
    };
    setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t));
    setSelectedTeacher(updated);
  };

  const deleteTeacher = (id: string) => {
    const teacher = teachers.find(t => t.id === id);
    if (!teacher) return;
    if (confirm(`¿ELIMINAR DOCENTE? El registro de ${teacher.fullName} se trasladará a la base de datos de EX-DOCENTES.`)) {
      const removedTeacher = { ...teacher, exitDate: new Date().toISOString().split('T')[0] };
      setExTeachers(prev => [...prev, removedTeacher]);
      setTeachers(prev => prev.filter(t => t.id !== id));
      setSelectedTeacher(null);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-blue-900 tracking-tight">Planta Personal Docente</h2>
          <p className="text-gray-500 font-bold uppercase text-[10px] tracking-[0.2em]">Escuela Secundaria Los Bulacios</p>
        </div>
        <div className="flex flex-wrap gap-3">
            <input type="file" className="hidden" ref={fileInputRef} accept=".xlsx" onChange={handleImport} />
            <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-2xl hover:bg-green-700 shadow-lg transition-all active:scale-95 text-xs font-black uppercase tracking-widest">
                <Upload size={18} /> Importar Planta (.xlsx)
            </button>
            <button onClick={() => exportExTeachersToExcel(exTeachers)} className="flex items-center gap-2 px-6 py-3 bg-gray-900 text-white rounded-2xl hover:bg-black shadow-lg transition-all active:scale-95 text-xs font-black uppercase tracking-widest">
                <Download size={18} /> BBDD Ex-Docentes
            </button>
        </div>
      </div>

      <div className="grid lg:grid-cols-12 gap-8">
         <div className="lg:col-span-4 bg-white rounded-3xl shadow-md border border-gray-50 flex flex-col h-[750px] overflow-hidden">
            <div className="p-6 border-b-2 border-gray-50 bg-gray-50/50 space-y-3">
                <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-900" size={20} />
                    <input 
                      className="w-full border-2 border-transparent bg-white rounded-2xl pl-12 pr-4 py-4 text-sm font-bold shadow-sm focus:border-blue-500 transition-all outline-none" 
                      placeholder="Buscar por Nombre o DNI..."
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="relative">
                    <Filter className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-900" size={18} />
                    <select 
                      value={courseFilter}
                      onChange={(e) => setCourseFilter(e.target.value as any)}
                      className="w-full border-2 border-transparent bg-white rounded-2xl pl-12 pr-10 py-3 text-sm font-bold shadow-sm focus:border-blue-500 transition-all outline-none appearance-none"
                    >
                      <option value="all">TODOS LOS CURSOS</option>
                      {['1', '2', '3', '4', '5', '6'].map(y => (
                        <option key={y} value={y}>{y}° AÑO</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={18} />
                </div>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
                {filteredTeachers.map(teacher => (
                    <div 
                      key={teacher.id}
                      onClick={() => { setSelectedTeacher(teacher); setIsEditing(false); }}
                      className={`group p-5 rounded-2xl cursor-pointer transition-all flex items-center justify-between border-2 ${selectedTeacher?.id === teacher.id ? 'bg-blue-600 border-blue-600 text-white shadow-xl translate-x-1' : 'bg-white border-transparent hover:border-blue-100 text-gray-700 hover:bg-blue-50'}`}
                    >
                        <div>
                          <p className={`font-black text-lg leading-tight ${selectedTeacher?.id === teacher.id ? 'text-white' : 'text-blue-900'}`}>{teacher.fullName}</p>
                          <p className={`text-[10px] font-black uppercase tracking-widest mt-1 ${selectedTeacher?.id === teacher.id ? 'text-blue-200' : 'text-gray-400'}`}>Legajo: {teacher.legajo} • {teacher.hours} Horas</p>
                        </div>
                        <button 
                          onClick={(e) => { e.stopPropagation(); deleteTeacher(teacher.id); }}
                          className="w-10 h-10 rounded-full bg-red-600 text-white flex items-center justify-center shadow-lg hover:bg-red-700 transition-all active:scale-90"
                          title="Eliminar Docente"
                        >
                          <Trash2 size={18} />
                        </button>
                    </div>
                ))}
                {filteredTeachers.length === 0 && (
                  <div className="p-8 text-center text-gray-400 italic text-sm font-medium">
                    No se encontraron docentes con estos criterios.
                  </div>
                )}
            </div>
         </div>

         <div className="lg:col-span-8">
            {selectedTeacher ? (
                <div className="bg-white rounded-3xl shadow-xl border border-gray-50 p-10 space-y-10 animate-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col md:flex-row justify-between items-start gap-6 border-b-2 border-gray-50 pb-8">
                     <div>
                       <div className="flex items-center gap-3 mb-2">
                          <h3 className="text-4xl font-black text-blue-900 tracking-tighter leading-none">{isEditing ? tempTeacher?.fullName : selectedTeacher.fullName}</h3>
                          <span className="px-3 py-1 bg-green-100 text-green-700 text-[10px] font-black rounded-full uppercase tracking-widest">Activo</span>
                       </div>
                       <p className="text-gray-400 font-bold uppercase text-xs tracking-widest">Legajo Institucional: {selectedTeacher.legajo}</p>
                     </div>
                     <div className="flex gap-2">
                        <button 
                            onClick={handleEditToggle}
                            className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg transition-all active:scale-95 ${isEditing ? 'bg-green-600 text-white hover:bg-green-700' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
                        >
                            {isEditing ? <><Save size={18}/> Guardar Registro</> : <><Edit3 size={18}/> Editar Registro</>}
                        </button>
                        <button 
                           onClick={() => exportTeacherReportToExcel(selectedTeacher)}
                           className="flex items-center gap-2 px-6 py-3 bg-[#6B46C1] text-white rounded-2xl hover:bg-[#553C9A] shadow-lg transition-all font-black text-xs uppercase tracking-widest"
                        >
                           <FileText size={18} /> Generar Informe
                        </button>
                     </div>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">DNI / Documento</p>
                        {isEditing ? <input className="w-full bg-white border-b-2 border-blue-500 p-1 font-bold" value={tempTeacher?.dni} onChange={e => setTempTeacher({...tempTeacher!, dni: e.target.value})} /> : <p className="font-black text-blue-900 text-xl">{selectedTeacher.dni}</p>}
                      </div>
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Contacto Directo</p>
                        {isEditing ? <input className="w-full bg-white border-b-2 border-blue-500 p-1 font-bold" value={tempTeacher?.phone} onChange={e => setTempTeacher({...tempTeacher!, phone: e.target.value})} /> : <p className="font-bold text-gray-800">{selectedTeacher.phone || 'No registrado'}</p>}
                        <p className="text-[10px] text-blue-500 font-bold truncate">{selectedTeacher.email}</p>
                      </div>
                      <div className="space-y-1 p-5 bg-gray-50 rounded-2xl border-2 border-gray-50">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Fecha Ingreso</p>
                        <p className="font-black text-blue-900 text-xl">{selectedTeacher.entryDate}</p>
                      </div>
                   </div>

                   <div className="bg-blue-900/5 p-8 rounded-3xl border-2 border-blue-900/10">
                      <h4 className="font-black text-blue-900 mb-6 flex items-center gap-3 uppercase text-lg tracking-tight"><GraduationCap size={24}/> Asignación de Espacios Curriculares</h4>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end mb-6">
                        <div>
                          <label className="text-[10px] font-black text-gray-400 uppercase block mb-2 ml-2">Seleccionar Año</label>
                          <select className="w-full border-2 border-gray-100 rounded-2xl p-4 text-sm font-bold bg-white outline-none focus:border-blue-500 transition-all" value={assignCourse} onChange={e => setAssignCourse(e.target.value as any)}>
                            {['1','2','3','4','5','6'].map(y => <option key={y} value={y}>{y}° Año</option>)}
                          </select>
                        </div>
                        <div>
                          <label className="text-[10px] font-black text-gray-400 uppercase block mb-2 ml-2">Espacio Curricular</label>
                          <select className="w-full border-2 border-gray-100 rounded-2xl p-4 text-sm font-bold bg-white outline-none focus:border-blue-500 transition-all" value={assignSubject} onChange={e => setAssignSubject(e.target.value)}>
                            <option value="">Seleccionar Materia...</option>
                            {SUBJECTS_BY_YEAR[assignCourse].map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                        </div>
                        <button onClick={assignWork} className="bg-blue-900 text-white p-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl active:scale-95">Asignar Espacio</button>
                      </div>
                      <div className="flex flex-wrap gap-3">
                        {selectedTeacher.assignedCourses.map((c, i) => (
                          <div key={i} className="flex items-center gap-3 bg-white border-2 border-blue-100 px-5 py-3 rounded-2xl text-blue-900 text-sm font-black shadow-sm group">
                            <span>{c.course}° AÑO - {c.subject}</span>
                            <button onClick={() => { if(confirm('¿Desasignar materia?')) { const updated = {...selectedTeacher, assignedCourses: selectedTeacher.assignedCourses.filter((_, idx) => idx !== i)}; setTeachers(prev => prev.map(t => t.id === updated.id ? updated : t)); setSelectedTeacher(updated); } }} className="text-gray-300 hover:text-red-600 transition-colors"><X size={18}/></button>
                          </div>
                        ))}
