                 <button onClick={() => handleManualAttendance('tarde')} className="bg-yellow-500 text-white px-7 py-3 rounded-2xl hover:bg-yellow-600 text-xs font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Tarde</button>
                 <button onClick={() => handleManualAttendance('ausente')} className="bg-red-500 text-white px-7 py-3 rounded-2xl hover:bg-red-600 text-xs font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Ausente</button>
