                          <td className="p-5">
                             <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest
                               ${att.type === 'presente' ? 'bg-blue-100 text-blue-700' : att.type === 'ausente' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}
