                                            Inasistencia Justificada
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="text-center py-10 opacity-40 italic font-medium">
                                    <p className="text-sm">No existen registros administrativos para esta fecha seleccionada.</p>
                                </div>
                            )}
